import{a as o}from"./chunk-2RJSKV3I.js";import{a as n}from"./chunk-B64NNECB.js";import"./chunk-U37H3HIF.js";var a=o(n,["학생 이름 가리기","입력된 이름과 직접 그린 가림 상자는 검게 칠해져요. 손으로 쓴 이름은 따로 가림 상자를 그려야 해요.","내보내지 못함: {list}. 나머지는 내려받았어요.",{one:"파일 이름은 “{name}”이 돼요.",other:"파일 이름은 “{name}”이 되고, {n}개가 ZIP 하나에 담겨요."},"먼저 상, 중, 하 답안지를 고르세요","기준 답안지","기준 답안지","이걸 {lv} 기준 답안지로 지정","파일을 만드는 중…","{who} 대신 이걸 {lv} 답안지로 지정","다른 답안지 대신 이걸 {lv} 답안지로 지정","{lv}(내보낼 페이지 없음)","아직 고르지 않음","{lv} 답안지예요. 다시 클릭하면 해제돼요.","기준 답안지 내보내기","채점하면서 상\xB7중\xB7하 답안지를 고르세요: 점수 아래에서 상, 중, 하를 클릭합니다.","이름은 답안지에 있는 그대로 남아요.","기준 답안지 {n}개를 ZIP 하나로 저장했어요.","“{name}”을(를) 저장했어요.","{lv} 기준 답안지예요. 돌려주기에 있어서 바로 내보낼 수 있어요.","학교에서 총괄 평가마다 보관하는 상\xB7중\xB7하 답안지예요. 돌려주기에서 세 개 모두를 이름이 있는 것과 이름을 가린 것으로 내보내요.","문제가 생겼어요: {e}","의견란에 이미 있는 내용 아래에 추가(체크를 해제하면 바꾸기)","의견란에 넣기","그 ZIP을 열 수 없어요","코드","피드백","피드백","{ai}에서 가져오기","학생과 짝짓기","학생 {of}명 중 {n}명을 짝지었어요.",{one:"아직 피드백이 없는 제출물 1개:",other:"아직 피드백이 없는 제출물 {n}개:"},"{ai}에 이것들을 부탁하는 메모 복사","같은 형식으로 다음 코드의 피드백을 이어서 써 주세요: {codes}","복사했어요. {ai}에 붙여 넣으세요.",{one:"답변 1개에 아직 [name]이 남아 있어요. 의견란에서 학생 이름으로 바꾸거나 빼세요.",other:"답변 {n}개에 아직 [name]이 남아 있어요. 의견란에서 학생 이름으로 바꾸거나 빼세요."},"아직 코드를 찾지 못했어요. 각 블록은 S-7QK4 같은 코드로 시작해야 해요.",{one:"코드 1개가 이 과제에 속하지 않아요.",other:"코드 {n}개가 이 과제에 속하지 않아요."},"이 과제에 없음","파일 열기…","학생별 폴더로 제출물 다운로드",{one:"코드로 이름 붙은 제출물 1개를 학생별 폴더로 다시 정리할 수 있어요.",other:"코드로 이름 붙은 제출물 {n}개를 학생별 폴더로 다시 정리할 수 있어요."},"{ai}의 답변",{one:"의견란 1개에 피드백을 넣었어요.",other:"의견란 {n}개에 피드백을 넣었어요."},"넣기 전에 한번 읽어 보세요.","{ai}의 답변을 여기에 붙여 넣거나, 받은 파일(CSV, 텍스트, ZIP)을 여세요. 각 코드는 이 브라우저 안에서 학생과 짝지어져요.","학생","{ai}에서 받음 - {name}","평균","숫자를 띄어서 입력하세요. 예: 4 3.5 3",{one:"평균 {a}, 합계 {s}, 숫자 {n}개",other:"평균 {a}, 합계 {s}, 숫자 {n}개"},"마지막 글자 지우기","지우기","계산기 닫기","기록 지우기","기록","답이 여기에 보여요.","만점","점수를 백분율로","점수를 입력하면 백분율이 보여요.","{p}% ({s}%)","성적 척도로 {p}%, 그대로 {s}%","입력하거나 탭하세요. 예: 3.5+4+3","점수","점수 스티커","답안지에서 붙일 곳을 클릭하세요","스티커: {s}","계산식","계산기","점수로 쓰기","이 숫자를 열려 있는 학생의 점수 칸에 넣어요","점수를 {n}(으)로 정했어요","전체 {n}","모든 답안지를 확인했어요","뒤로",{one:"상자 {n}개",other:"상자 {n}개"},"이 페이지를 보여 줄 수 없어요.","답안지 {n}/{of}","아직 이 답안지를 그리는 중이에요","마지막 상자를 모든 답안지에 적용","모든 답안지를 확인했어요.",{one:"그 가림을 답안지 {n}개에 더 추가했어요",other:"그 가림을 답안지 {n}개에 더 추가했어요"},"답안지 찾기","표시됨 {n}","이름 위로 드래그하면 가려져요. 상자를 클릭하면 빠져요. {key}로 실행 취소해요.","마지막 답안지였어요","“{q}”와(과) 일치하는 학생이 없어요.","확인할 PDF나 그림이 없어요","아직 확인 안 함","되돌릴 것이 없어요","보여 줄 것이 없어요.","확인함","제출물","{of}개 중 {n}개 확인","가림이 잘 됐어요","가림이 잘 됐어요, 완료",", 아직 확인 안 함",", 확인함","가림 확인","미확인 {n}","가림을 뺐어요. {key}를 누르면 되돌려요.","미확인으로 표시","약 {v}","{n}개는 도우미에게서 가져온 피드백처럼 한꺼번에 바뀌어서 순서를 알 수 없어요","뒤로","이 페이지를 그릴 수 없어요.","매긴 순서대로의 점수입니다. 같은 점수가 차트 아래 목록에도 있습니다.","{who}, {v}/{max}점, {n}개 중 {k}번째로 채점","답안지가 너무 적어 말할 수 없습니다.","채점이 엄격해졌는지 너그러워졌는지 말하려면 적어도 {n}이(가) 필요해요. 그보다 적으면 보이는 패턴은 대부분 우연이에요.",{one:"지금까지 시간 기록이 있는 답안지는 {n}개뿐이에요.",other:"지금까지 시간 기록이 있는 답안지는 {n}개뿐이에요."},"지금까지 시간 기록이 있는 답안지가 없어요.","처음 채점","각 점수가 마지막으로 바뀐 시점을 기준으로 하므로, 나중에 다시 본 답안지는 늦은 것으로 칩니다. 확정된 점수만.","채점하면서 더 엄격해지거나 너그러워졌나요?","같은 점수, 나란히",{one:"뒤쪽 답안지의 점수가 약 {n}점 높았어요.",other:"뒤쪽 답안지의 점수가 약 {n}점 높았어요."},"답안지가 {n}개면 이건 우연일 가능성이 커요.","그럴 수도 있지만, 아직 판단하기엔 일러요.","마지막 채점","제외됨: {list}.","답안지 {n}개에서 우연히 생기는 차이보다 커요.","한번 살펴볼 만해요.","목록으로 보기",{one:"뒤쪽 답안지의 점수가 약 {n}점 낮았어요.",other:"뒤쪽 답안지의 점수가 약 {n}점 낮았어요."},{one:"{n}장",other:"{n}장"},"다음 페이지","답안지가 없어요.","여기 보여 줄 PDF나 그림이 없어요. 답안지를 열어서 읽으세요.",{one:"{n}개는 시간 기록이 없어요(앱이 기록을 시작하기 전에 채점했거나, 답안지에서 읽어 온 것)",other:"{n}개는 시간 기록이 없어요(앱이 기록을 시작하기 전에 채점했거나, 답안지에서 읽어 온 것)"},"이 정도 차이는 우연히 자주 생겨요.","답안지가 {n}개뿐이면 큰 변화만 드러나요. 그래서 채점이 일정했다고 단정할 수는 없어요.","뚜렷한 변화가 없어요.","확정된 점수가 같은 답안지가 아직 없습니다.","처음 {k}개는 평균 약 {a}점, 마지막 {k}개는 약 {b}점이에요({max}점 만점).","순서","{b}페이지 중 {a}페이지","답안지","점수를 고르면 그 답안지들을 나란히 볼 수 있어요.","이전 페이지","시간 기록이 있는 답안지가 너무 적음",{one:"뒤쪽 답안지가 약 {n}점 높음",other:"뒤쪽 답안지가 약 {n}점 높음"},{one:"뒤쪽 답안지가 약 {n}점 낮음",other:"뒤쪽 답안지가 약 {n}점 낮음"},"뚜렷한 변화 없음","답안지가 {n}개보다 적으면 루브릭 항목을 하나씩 분석하지 않아요. 항목 하나만으로는 오차가 너무 커요.","{v}점 받은 답안지","점수","채점됨","답안지가 하나뿐인 점수는 목록에 없어요.","학생","채점하면서 점점 너그러워졌을 수도 있고, 그냥 그 답안지들이 더 좋았을 수도 있어요. 점수가 같은 앞쪽과 뒤쪽 답안지를 몇 개 비교해 보세요.","채점하면서 점점 엄격해졌을 수도 있고, 그냥 그 답안지들이 더 약했을 수도 있어요. 점수가 같은 앞쪽과 뒤쪽 답안지를 몇 개 비교해 보세요.",{one:"확인할 답안지 {n}개: 답안지의 성적이 내 성적과 다르거나, 성적이 둘 이상이거나, 성적이 아닐 수도 있는 숫자가 있어요.",other:"확인할 답안지 {n}개: 답안지의 성적이 내 성적과 다르거나, 성적이 둘 이상이거나, 성적이 아닐 수도 있는 숫자가 있어요."},"모두 보기","이것만 보기","윗줄의 점수","성적이 없는 파일도 보기 (내려받는 성적표에도 같은 줄이 들어가요)","답안지에서 찾은 성적도 보기 (Grading Studio에서 준 점수가 항상 우선해요)","뒤로","이 파일에는 표시도 입력된 글자도 없어요. Kami에서 채점했다면 표시가 파일에 저장되지 않았을 수 있어요. '직접 상자로 표시'를 써 보세요.","직접 상자로 표시","상자 그림(다시 드래그하면 바뀌어요)","학생 {n}/{of} \xB7 답안지 {p}/{pof}","성적 주위로 드래그해 상자를 그리세요. 저장한 뒤 다음 답안지로 넘어가요. 왼쪽\xB7오른쪽 화살표로 앞뒤로 이동하고, Esc를 누르면 끝나요.","성적에 상자 그리기","직접 상자로 표시함","다시 포함","취소","이 파일을 읽을 수 없었어요","이 파일을 열 수 없어요. 건너뛰기를 클릭하세요.","확인할 것 {n}개","확인할 것 {n}개","{v} 복사함","클릭해서 복사","완료","각 성적을 직접 상자로 표시","답안지에는 다르게 적혀 있어요","{of}개 중 {n}개 피드백 완료","첫 페이지","표시는 있지만 입력된 글자가 없어서, 성적이 손글씨이거나 평면화되었을 수 있어요. '직접 상자로 표시'를 써 보세요.","답안지에서 찾음: {list}","'{text}'에서","각 줄은 그 학생 폴더 안에 있는, 줄에 적힌 파일로 만들어요. 그림을 클릭하면 그 학생이 열리고, 점수를 클릭하면 복사돼요.","이게 성적인가요?","마지막 답안지였어요","마지막 페이지","제외","제외됨 (표시 없음).","각 답안지에서 성적을 찾는 중…","이 답안지에는 성적이 여러 개 있어요. 어느 것을 쓸지 고르세요.","성적 {n}개 찾음, 확인하세요","아직 성적 없음.","이 답안지에는 아직 점수 도장이 없어요. 총점 옆의 '도장'으로 점수를 찍으세요.","상자로 표시할 답안지가 없어요","고를 답안지가 없어요","아직 찾은 성적 없음","성적 아님","아직 형광펜으로 표시하지 않은 기준이 있어요","제출한 것 없음","채점하지 않은 파일만 있음, 제외됨","이 학생 열기",{one:"파일 {n}개에 표시가 없어서 여분의 답안지로 보고 제외했어요.",other:"파일 {n}개에 표시가 없어서 여분의 답안지로 보고 제외했어요."},"숨기기","보기","{p}페이지","답안지에","(일부)","읽은 값","답안지에서 {n}개 읽음","직접 상자로 표시함 \xB7 다시 하기","'{v}'은(는) 성적이 아니라고 정했어요.","'{v}'을(를) 성적으로 정했어요.","점수","{of}개 중 {n}개 채점됨","입력된 글자에서 성적을 찾지 못했어요: '{text}'","성적표","건너뛰기(성적 없음)","모든 답안지에서 같은 위치","공통 위치 바꾸기","성적을 적는 곳 주위로 드래그해 상자를 그리세요. 모든 답안지에서 같은 위치를 잘라 내서, 손으로 쓴 성적도 찾아요.","공통 위치 그만 쓰기","모든 답안지에서 같은 위치","페이지","성적 위치 고르기","이 위치 사용","표","각 부분을 내 표시만 남게 자르기","보이는 대로 입력","그림에 보이는 점수를 입력하세요","입력된 글자: '{text}'","입력된 글자: '{text}' \xB7 {p}페이지","실행 취소","이걸로 쓰기","성적 보기","폴더와 파일","Word 파일","Word 루브릭","Word 파일을 준비하는 중…","내가 준 점수","Grading Studio에서 내가 준 점수: {v}","내가 준 점수 (일부)","내가 준 점수 (반영되는 시도)","가림 확인…",{one:"답안지 {of}개 중 {n}개 확인했어요.",other:"답안지 {of}개 중 {n}개 확인했어요."},"답안지를 세는 중…","가림 확인에서 이름 위로 드래그해 상자를 그린 다음, 모든 답안지에 적용하세요.","먼저 이름을 가리세요.",{one:"이것부터 확인하세요:",other:"이것들부터 확인하세요:"},"이름을 찾는 중…","확인할 PDF나 그림이 없어요.","이름이 다시 보여요","이름 숨김: 답안지는 무작위 순서, 이름은 가려짐","답안지는 답안지 1, 답안지 2…처럼 무작위 순서로 보여요. 점수는 그대로 맞는 학생에게 들어가요.","새로 섞고 시작","섞었어요: 새로운 무작위 순서","이름 숨기기 시작","이름 숨기기",{one:"이 Word 답안지에는 이름이 보여요.",other:"이 Word 답안지들에는 이름이 보여요."},{one:"이 답안지에 이름이 보일 수 있어요.",other:"이 답안지들에 이름이 보일 수 있어요."},{one:"가리려면 PDF 페이지로 바꾸세요.",other:"가리려면 PDF 페이지로 바꾸세요."},"일관성","개요","분석 보기","이 과제에서 채점할 평가 기준을 체크하세요. 각각 0부터 {top}까지 점수를 매기는 항목이 돼요. 과제 하나는 보통 두세 개를 평가해요.","{cls}은(는) MYP 평가 기준으로 채점해요.","취소","이 과제의 평가 기준 고르기","평가 기준","이 과제가 평가하는 기준: {list}","수준, 0부터 {top}까지",{one:"답안지 {n}개에 이미 준 수준이나 점수가 사라져요. 실행 취소로 되돌릴 수 있어요.",other:"답안지 {n}개에 이미 준 수준이나 점수가 사라져요. 실행 취소로 되돌릴 수 있어요."},"평가 기준 {of}개 중 {n}개 채점함","항목의 각 수준이 무슨 뜻인지는 직접 써요. 나중에 루브릭 설정에서 내 기술어를 붙여 넣으세요.","평가 기준을 하나 이상 체크하세요","저장","도장","답안지에 수준 찍기: {text}","이 과제가 평가하는 기준","다시 묻기","확인할 것 {n}개","확인해 주기 전까지 점수는 숨겨져요.","{cls}에서","이전 {n}개","이전 {n}개 \xB7 최근 {pct}","“{name}”은(는) 이 학생이 아니라고 정했어요.","일치 없음","앱에 점수가 없어요. 답안지에는 있을 수 있어요.","다른 학생","이 이름은 {cls} 명단과 확실히 일치하지 않아서, 이전 과제를 확실하게 연결할 수 없어요.","이 다운로드에는 명단이 선택되지 않아서, 이전 과제를 확실하게 연결할 수 없어요.","답안지에","일부","“{name}”","같은 학생","면제","지각","미제출","이전 과제","실행 취소","{where}에 있어요.","다운로드 {n}개","이름이 비슷하지만 확실히 일치하지는 않아요.","이름은 같지만 확인할 명단이 없어요.","이름은 같지만 {cls}에 있어요. 다른 사람일 수 있어요.","“{name}”이(가) 이 학생이라고 정했어요.","문제마다 순서대로 드래그해 상자를 그리세요. 상자는 겹쳐도 돼요. 상자의 번호를 드래그하면 옮겨져요. 상자를 클릭하면 모서리로 크기를 바꾸거나 표시가 들어갈 곳을 정할 수 있어요. 그다음 문제마다 배점, 채점 방식(정답/오답, 또는 단답형은 0~2 같은 척도), 정답이 있으면 정답을 넣으세요. 정답은 돌려주는 답안지에 금색 메모로 넣을 수 있어요.","정답 메모","모든 문제","감점된 곳","끄기","모든 답안지에서, 정답이 있는 문제마다 옆에 정답을 적은 금색 메모가 들어가요.","학생이 감점된 문제마다 옆에 정답을 적은 금색 메모가 들어가요.","입력한 정답은 채점하는 동안 나만 봐요.","{q}번 문제의 정답 메모로 가는 선이 시작되는 곳이에요. 드래그하면 옮겨져요.","정답 선 시작 위치","표시 옆","각 상자 오른쪽","금색 핀을 드래그하지 않았다면.","각 상자 아래","표시 옆","상자 오른쪽","상자 아래","답안지별로 옮긴 정답 메모는 저장하면 제자리로 돌아가요.","취소","페이지를 클릭하세요…","평가 기준","{q}번 문제의 평가 기준","이 상자 빼기","목표","{q}번 문제의 학습 목표","목표 없음","채점 방식","✓와 ✗","점수","오답에 ✗","그대로 두기","답","정답","선택 사항","고른 상자 단축키: 화살표로 이동, Shift + 화살표로 크기 조절, Ctrl D로 바로 아래에 복사, Del 키로 빼기.","채점됨","정답 선:","{at}에서 시작해요. 금색 핀을 드래그하면 바뀌어요.","{at}(으)로 되돌리기","드래그한 금색 핀에서 시작해요","평가 기준 {list}의 수준을 마저 채우거나 지우세요","평가 기준 {k}의 수준 {n} 최저 점수","지우기","고르게 나누기","{n}칸을 모두 채우세요. 각 칸은 앞 칸 이상의 점수여야 해요.","점수를 수준으로","아직 수준이 없어요. 이 평가 기준은 점수만 보여요.","{n}점 만점","수준 {n}에는 {p}점이 필요한데, 이 문제들의 합은 {max}점이에요.","각 수준을 받는 최저 점수","여백에","여백으로 되돌리기","{q}번 문제 표시:","새 상자 채점 방식","합계 없음","아직 상자가 없어요","그릴 곳","{n}페이지","표시가 들어갈 곳이에요. 드래그하면 옮겨져요.","점수","답안지별로 옮긴 정답 메모 되돌리기 ({n})","질문","문제 이름","정답 / 오답","상자 저장","상자를 저장했어요","상자를 저장했어요. 이제 점수는 {n}점 만점이에요.","상자를 저장했어요. 이제 빠른 채점이 이 과제를 {n}점 만점으로 채점해요. 루브릭 점수는 저장된 채로 남지만 더 이상 반영되지 않아요.","표시 위치","각 상자 왼쪽","오른쪽","위치를 따로 고르지 않았다면","표시 위치 고르기","{n}페이지에서 {q}번 문제가 있는 곳을 고르세요","{n}문제, {pts}점 만점","{n}문제, {pts}점 만점","퀴즈 상자","합계","모든 문제를 채점하면 점수가 {n}페이지에 들어가요.","모든 문제를 채점하면 수준이 {n}페이지에 들어가요.","선택 사항: 답안지에 수준을 넣을 위치(예: A 6).","옮기기","선택 사항: 답안지에 점수를 넣을 위치(예: 18/20 = 90%).","위치 고르기","{n}점 중 {s}점의 뜻","각 점수의 뜻","0~{n}","채점하는 동안 버튼에 보여요","추가","+ 보기","빈 사본","브라우저가 인쇄 창을 막았어요","문제와 동그라미","취소","보기 {l}","보기 {l} 빼기","빼기","거짓","정답","정답: {k}","정답: {list}. 모두 고르고 다른 것은 고르지 않아야 점수를 받아요.","문제 유형","이것을 정답으로","객관식","해당하는 것 모두 고르기","학생 이름","글자를 클릭해 정답을 정하세요.",{one:"학생 {n}명분 인쇄…",other:"학생 {n}명분 인쇄…"},"인쇄할 내용","점수","단답형","학생은 줄 위에 써요. 교사 칸에서 0~{n} 점수 동그라미를 칠해 채점하면, 스캔이 그 점수도 읽어요. 비워 두고 빠른 채점에서 채점해도 돼요.","저장","퀴즈를 저장했어요","퀴즈를 저장했어요. 이번 변경으로 동그라미 위치가 바뀌니 다시 인쇄하세요. 전에 인쇄한 사본은 스캔이 읽을 수 없어요.","답안지만","정답 보기","퀴즈 만듦","{n}문제, {pts}점 \xB7 한 부에 {pages}페이지 \xB7 스캔 채점 {auto}개, 직접 채점 {sa}개","{n}번 문제","문제를 입력하세요","문제를 입력하세요(답안지에서는 선택 사항)","참/거짓","퀴즈 만들기","퀴즈 편집","참","위로 이동","내 도우미","전체","여기는 모두 채점했어요. 채점한 것을 보려면 전체를 고르세요.","학생 답안지에 금색으로 들어가요. 답이 들어갈 곳은 상자에서 바꿀 수 있어요.","답","여백 의견","페이지 위 글","상자","문제별","학생별","지우기","빠른 채점 닫기","의견","이 답안지에 의견이나 글 쓰기 (C)","이 답만 들어가고, 위에 문제와 정답이 붙어요. 학생 이름, 점수, 내 표시, 파일 이름은 빠지고, 이름 가림은 칠해져요. 하지만 학생의 글씨와 말은 그대로 보여요.","어디에도 보내지 않아요. 직접 어딘가에 붙여 넣기 전까지 그림은 이 컴퓨터에만 있어요.","그림에 보이는 것.","알겠어요","색","{q} 그림을 복사했어요. {ai}에 붙여 넣고 물어보세요.","⧉ 복사","이 답을 그림으로 복사해서 도우미나 어디에든 붙여 넣을 수 있어요. 이름, 점수, 표시는 들어가지 않아요 (P)","{of}개 중 {n}개 채점함","페이지를 그리는 중…","전체 너비","0.5점 더하기 또는 빼기 (H)","키: 숫자는 그 점수, H는 \xBD 더하기,","C 의견, P 그림 복사, 화살표로 이동, 스페이스 바 전체 페이지, Ctrl Z 실행 취소, [ ]로 문제 이동. 표시를 드래그하면 그 답안지에서만 옮겨져요.","답을 클릭하면 ✗가 표시되고, 다시 클릭하면 빠져요. 키: 1 정답, 0이나 X 오답,","답을 클릭하면 ✗가 표시되고, 다시 클릭하면 빠져요. 키: ↑ ↓로 이동, 숫자는 그 점수, C 의견, P 그림 복사, 스페이스 바 전체 페이지, Ctrl Z 실행 취소, [ ]로 학생 이동.","드래그: 이 답안지 위치 맞추기","클릭: 오답 / 정답. 드래그: 이 답안지 위치 맞추기","색","득점에 따라","만점: 2/2 \xB7 부분 점수: 1/2 \xB7 0점: 0/2. 합계와 점수 도장은 ✗ 색 그대로예요.","만점은 ✓ 색, 부분 점수는 호박색, 0점은 ✗ 색","이미 준 표시도 같이 바뀌어요.","✓ 정답","점수","✗와 같게","점수를 ✗ 색으로","표시 색","✗ 오답","정답이에요.","모든 답안지에 금색 메모로 들어가요.","이 문제에서 감점된 답안지에 금색 메모로 들어가요.","정답 메모가 꺼져 있어요. 상자에서 켜세요.","드래그하면 이 답안지에서만 이 표시를 옮겨요","이 페이지는 학생의 스캔에 없어요.","채점할 스캔 답안지가 없어요","채점 안 됨","들어갈 곳","의견:","{c} 의견","Enter로 저장, Esc로 취소","학생 답안지에 쓸 내용을 입력하세요…","글:","클릭해서 바꾸기","{n} / {of}","학생 답안지 열기","⤢ 전체 페이지","{q}번 문제, {n}페이지","뒤로 (Esc)","학생의 전체 페이지 보기 (스페이스 바)","이 답안지에서 표시가 들어갈 곳이에요. 드래그하면 이 답안지에서만 옮겨져요.","{n}점","{n}점","다음 문제","질문","이전 문제","{q}번 문제","위치 초기화","이 표시를 문제의 표시 위치로 되돌리기","나머지는 정답 처리","나머지에 {n} 주기","정답 ({n})","{n}점, 정답 또는 오답","{n}점, 정답 또는 오답","다음 학생","학생","이전 학생","저장","이 브라우저는 그림을 복사할 수 없어서 {q}을(를) 그림 파일로 저장했어요.","0~{n}점 척도","보여 줄 답","크기","빠른 채점","답 보기","오답 (0)","다시 읽기","모든 페이지를 다시 읽어요. 이미 있는 답은 그대로 남아요.","모든 점수는 빠른 채점에서 바꿀 수 있어요. Ctrl Z를 누르면 스캔이 준 점수를 되돌려요.","다음","답안지에서 이 퀴즈의 페이지를 찾지 못했어요","없음","바뀐 것이 없어요","확인할 것이 없어요.","{n}페이지는 퀴즈를 마지막으로 바꾸기 전에 인쇄돼서 읽지 않았어요. 빠른 채점에서 채점하세요.","1페이지는 퀴즈를 마지막으로 바꾸기 전에 인쇄돼서 읽지 않았어요. 빠른 채점에서 채점하세요.","이것들은 분명하지 않아서 자동으로 채점할 수 없었어요. 학생마다 의도한 답을 고르세요. 강조된 버튼이 스캔의 추측이에요.","{q}번 문제 \xB7 {why}","동그라미를 읽는 중…","점수 저장","점수 {n}개를 저장했어요","점수 1개를 저장했어요","학생 {who}명의 퀴즈에서 답 {n}개를 채점했어요","학생 {who}명의 퀴즈에서 답 {n}개를 채점했어요","확인 필요","읽은 페이지","읽은 답","읽은 답, 빈칸 {n}개","페이지의 코드로 찾은 학생","학생의 답","학생의 답","퀴즈 스캔 결과","너무 흐림","다른 동그라미에도 표시됨","점수 불분명","동그라미 두 개 칠함","불분명","내 점수","{ai}에 할 말","{ai}에서 가져오기","가림 확인","가림 다시 확인","나머지 {n}개 확인","{of}개 중 {n}개 확인","복사했어요. ZIP과 함께 {ai}에 붙여 넣으세요.","메시지 복사","복사하지 못했어요. 텍스트를 선택해 직접 복사하세요.","확인함({n})","{ai}와(과) 공유","{ai}에 줄 것","완료했어요. ZIP을 {ai}에 준 다음, 보내온 내용을 '가져오기'로 불러오세요.","{when}에 만듦.",{one:"{when}에 만듦. 확인 안 한 제출물이 1개 있어요.",other:"{when}에 만듦. 확인 안 한 제출물이 {n}개 있어요."},"이름을 가리고 사진 만드는 중 {n}/{of}","표시만","도우미와 공유","복사했어요. 표시 파일과 함께 {ai}에 붙여 넣으세요.","표시 파일 다운로드",{one:"완료: 학생 1명. 메시지와 함께 파일을 {ai}에 주세요.",other:"완료: 학생 {n}명. 메시지와 함께 파일을 {ai}에 주세요."},"표시 파일을 내려받으세요.","학생 피드백을 써 줬다면 답변을 가져오세요.","반 전체의 경향을 살펴보는 파일로, 이름은 들어 있지 않아요. 학생에게는 ZIP과 같은 코드가 붙고, 의견 속 이름은 [name]이 돼요. 제출물은 보내지 않으니 가림을 확인할 필요가 없어요.","의견과 페이지 위 텍스트","펜 표시와 체크 개수","루브릭 점수, 총점, 백분율, 상태","교정 부호와 스티커","형광펜을 칠하거나 동그라미를 치거나 의견을 단 단어","{ai} 열기",{one:"ZIP에 없음: 넣을 수 있는 제출물이 없는 학생 1명.",other:"ZIP에 없음: 넣을 수 있는 제출물이 없는 학생 {n}명."},"답안지와 표시","표시 읽는 중 {n}/{of}","가림을 확인하세요.","이름마다 위로 드래그해 상자를 그리세요. 이름이 모두 같은 자리에 있으면 한 번만 그려서 모든 제출물에 쓸 수 있어요.","ZIP을 내려받으세요.","이 메시지와 함께 {ai}에 주세요. 내용은 마음대로 바꿔도 돼요.","답변을 가져오세요.","이름이 없는 ZIP을 만들어 {ai}에 줄 수 있어요. 학생마다 무작위 코드가 붙고, 누가 누구인지 목록은 이 브라우저에만 남아요.","{ai}에 줄 때까지 내 컴퓨터에만 있어요.","아직 확인 안 함({n})","모든 페이지가 그림이 되어서, 숨은 글이나 파일 정보는 같이 가지 않아요.","가림 확인에서 상자를 그린 곳의 이름은 가려져요.","페이지에 입력된 이름은 어디에 있든 검게 가려져요. 이메일 주소와 긴 ID 번호도 마찬가지예요.","점수, 루브릭, 의견도 함께 가고, 이름은 [name]으로 바뀌어요.","PDF와 사진만 들어가요. Word 파일은 PDF 페이지로 바꾸기 전에는 들어가지 않아요.","들어가는 것","문제가 생겼어요: {e}","{ai}용 ZIP 다운로드","그래도 ZIP 다운로드","취소","그림을 복사했어요. 필요한 곳에 붙여 넣으세요.","복사하기","복사할 부분을 끌어서 고르세요.","복사할 부분을 끌어서 고르거나, 페이지를 클릭해 전체를 복사하세요.","Esc","좋은 예시로 저장","그림을 만들 수 없었어요. 더 작은 영역으로 해 보세요.","내 표시 포함","복사할 영역을 끌어서 고르세요.","영역을 끌어서 고르거나 페이지를 클릭하세요.","모든 것이 화면에 보이는 그대로예요.","답안지에서는 이름 가리기 부분이 칠해지고, 학생 이름과 파일 이름은 빠져요. 나머지는 화면에 보이는 그대로예요.","이 브라우저는 그림을 복사할 수 없어서 Screenshot.png로 저장했어요.","그다음","스크린샷","전체 화면","화면에 보이는 모든 것 (Enter)","관찰 목록에 추가","저장한 코멘트","아직 저장한 코멘트가 없어요. 코멘트 아래에서 저장하거나 설정 > 채점에서 추가하세요."],null);export{a as default};
